pinDefaults.template:
Read the search results for one step of a deep search.

Main question: {{question}}
This step: {{step}}

Search results:
{{hits}}

Return the facts with the note ids that support them, what changed over time, and what is missing.

Output JSON only, matching the schema.

Write a dossier that answers the question from the findings of a deep search.

Question: {{question}}
Plan: {{plan}}

Findings per step:
{{findings}}

Write a title, a narrative with inline citations [nt_...], a timeline, how the view evolved, the contradictions, forgotten items worth revisiting, suggestions, and a confidence statement. Use only the note ids in the findings.

Output JSON only, matching the schema.

data.codeBody:
d = data if isinstance(data, dict) else {}
seen, evidence = set(), []
pools = [first_notes or []] + [e.get("notes") or [] for e in (findings or []) if isinstance(e, dict)]
for pool in pools:
    for n in pool:
        nid = n.get("note_id") if isinstance(n, dict) else None
        if nid and nid not in seen:
            seen.add(nid)
            evidence.append({"note_id": nid, "title": n.get("title"), "occurred_at": n.get("occurred_at"),
                             "excerpt": n.get("excerpt")})
entity_ids = [x.get("entity_id") for x in (first_entities or []) if isinstance(x, dict) and x.get("entity_id")]
narrative = str(d.get("narrative") or "").strip()
if not narrative:
    raise ValueError("The dossier came back empty.")
lines = [narrative]
def section(title, items):
    rows = [str(i).strip() for i in (items or []) if str(i).strip()]
    if rows:
        lines.append("")
        lines.append("## " + title)
        lines.extend(["- " + r for r in rows])
section("Timeline", [str(t.get("at") or "") + ": " + str(t.get("event") or "") for t in (d.get("timeline") or []) if isinstance(t, dict)])
if str(d.get("evolution") or "").strip():
    lines.extend(["", "## How the view evolved", str(d.get("evolution")).strip()])
section("Contradictions", d.get("contradictions"))
section("Worth revisiting", d.get("forgotten"))
section("Suggestions", d.get("suggestions"))
if str(d.get("confidence") or "").strip():
    lines.extend(["", "## Confidence", str(d.get("confidence")).strip()])
return {"title": str(d.get("title") or question)[:120], "body": "\n".join(lines), "narrative": narrative,
        "evidence": evidence, "evidence_note_ids": [e["note_id"] for e in evidence], "entity_ids": entity_ids}

arguments = {}
if kind is not None:
    arguments["kind"] = kind
if title is not None:
    arguments["title"] = title
if body is not None:
    arguments["body"] = body
if evidence_note_ids is not None:
    arguments["evidence_note_ids"] = evidence_note_ids
if entity_ids is not None:
    arguments["entity_ids"] = entity_ids
return {"tool_calls": [{"name": "note_insight_write", "call_id": "write", "arguments": arguments}]}

r = results[0] if isinstance(results, list) and results else None
if not isinstance(r, dict):
    raise ValueError("note_insight_write returned no result.")
if not r.get("success"):
    raise ValueError(str(r.get("error") or "note_insight_write failed."))
out = r.get("output")
if not isinstance(out, dict):
    raise ValueError("note_insight_write returned something other than an object.")
return dict(out, tool_output=out)

d = data if isinstance(data, dict) else {}
ev = d.get("evolution")
return {"response": narrative, "answer": narrative, "evidence": evidence,
        "evolution": {"summary": ev} if ev else {}, "open_loops": d.get("forgotten") or [],
        "follow_ups": d.get("suggestions") or [], "dossier_note_id": note_id}
